$mutex=$null;$owns=$false;$TempRepo=$null
$env:GIT_TERMINAL_PROMPT='0';$env:GCM_INTERACTIVE='never'
function GitAt {
 param([string]$Dir,[string[]]$A,[int[]]$Ok=@(0))
 $si=[Diagnostics.ProcessStartInfo]::new();$si.FileName=$Git;$si.WorkingDirectory=$Dir;$si.UseShellExecute=$false;$si.CreateNoWindow=$true
 $si.RedirectStandardOutput=$true;$si.RedirectStandardError=$true;$si.StandardOutputEncoding=$Utf8;$si.StandardErrorEncoding=$Utf8
 foreach($x in (@('-C',$Dir,'-c','core.quotepath=false')+$A)){[void]$si.ArgumentList.Add($x)}
 $p=[Diagnostics.Process]::new();$p.StartInfo=$si
 try{
  [void]$p.Start();$o=$p.StandardOutput.ReadToEndAsync();$e=$p.StandardError.ReadToEndAsync()
  if(-not $p.WaitForExit(300000)){$p.Kill($true);throw "Git excedeu prazo: $($A -join ' ')"}
  $text=$o.GetAwaiter().GetResult();$err=$e.GetAwaiter().GetResult()
  if($p.ExitCode -notin $Ok){throw "Git falhou ($($p.ExitCode)): $($A -join ' ') $err"}
  [pscustomobject]@{Code=$p.ExitCode;Text=$text.TrimEnd([char[]]"`r`n")}
 }finally{$p.Dispose()}
}
function G([string[]]$A,[int[]]$Ok=@(0)){return GitAt -Dir $Root -A $A -Ok $Ok}
function Canon([byte[]]$Bytes){
 $text=$StrictUtf8.GetString($Bytes);if($text.Length -gt 0 -and $text[0] -eq [char]0xFEFF){$text=$text.Substring(1)}
 $normalized=$text.Replace("`r`n","`n").Replace("`r","`n")
 return [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($Utf8.GetBytes($normalized))).ToLowerInvariant()
}
try{
 if(-not(Test-Path -LiteralPath $CfgPath)-or -not(Test-Path -LiteralPath $SyncPath)){throw 'Sincronizador existente nao encontrado. Nao inicializei outro repositorio.'}
 $hash=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($Root.ToLowerInvariant()))).Substring(0,20)
 $mutex=[Threading.Mutex]::new($false,"Local\TheBridgeGitSync-$hash")
 try{$owns=$mutex.WaitOne(0)}catch [Threading.AbandonedMutexException]{$owns=$true}
 if(-not $owns){throw 'Sincronizador ativo: Ctrl+C na janela dele antes de instalar.'}
 if(@(Get-Process -Name git -ErrorAction SilentlyContinue).Count -gt 0){throw 'Existe operacao Git ativa. Aguarde antes de instalar.'}
 if((G -A @('branch','--show-current')).Text -ne 'main'){throw 'A pasta nao esta na main.'}
 foreach($op in @('index.lock','MERGE_HEAD','CHERRY_PICK_HEAD','REVERT_HEAD','rebase-merge','rebase-apply')){
  if(Test-Path -LiteralPath (Join-Path $Root ('.git/'+$op))){throw "Git ocupado: $op"}
 }
 $origin=(G -A @('remote','get-url','origin')).Text
 if(($origin.TrimEnd('/') -replace '\.git$','') -ne 'https://github.com/MuriloFangel/the-bridge'){throw 'Origin diferente do esperado.'}
 $null=G -A @('fetch','origin')
 $head=(G -A @('rev-parse','HEAD')).Text;$remoteHead=(G -A @('rev-parse','refs/remotes/origin/main')).Text
 if($head -ne $remoteHead){throw 'Main local e remota diferem. Nao fiz pull/reset. Reconcilie antes.'}
 $blob=(G -A @('hash-object','--path=Sincronizar-GitHub.ps1',$SyncPath)).Text
 if($blob -ne $ExpectedBlob){throw 'O sincronizador local difere da versao auditada para estes hooks. Nao substitui sua versao por outra; envie o arquivo atual.'}
 $source=[IO.File]::ReadAllText($SyncPath)
 $stageAnchor="    return (G -Arguments @('write-tree')).Text"
 $pushAnchor='    Say "GitHub atualizado: main @ $sha"'
 $functionAnchor='function Push-Current {'
 foreach($anchor in @($stageAnchor,$pushAnchor,$functionAnchor)){
  if(([regex]::Matches($source,[regex]::Escape($anchor))).Count -ne 1){throw 'Anchor ausente/duplicado. Nao fiz patch aproximado.'}
 }
 $newFunction=@'
# BEGIN BRIDGE TRACE HOOK V1
function Invoke-BridgeTrace {
    param([ValidateSet('BeforeCommit','AfterPush')][string]$Mode)
    $worker=Join-Path $Root 'tools/Bridge-Rastreabilidade.ps1'
    if(-not(Test-Path -LiteralPath $worker)){throw 'STOP: helper de rastreabilidade ausente.'}
    try {
        $run=Invoke-Program -Exe (Join-Path $PSHOME 'pwsh.exe') -Arguments @('-NoProfile','-ExecutionPolicy','Bypass','-File',$worker,'-ProjectPath',$Root,'-Mode',$Mode)
    } catch { throw ('STOP: Rastreador impediu a operacao: '+$_.Exception.Message) }
    if(-not [string]::IsNullOrWhiteSpace($run.Text)){Say $run.Text}
}
# END BRIDGE TRACE HOOK V1
'@
 $newSource=$source.Replace('#requires -Version 7.0','#requires -Version 7.2').Replace($stageAnchor,"    Invoke-BridgeTrace -Mode BeforeCommit`n"+$stageAnchor)
 $newSource=$newSource.Replace($functionAnchor,$newFunction+"`n"+$functionAnchor)
 $newSource=$newSource.Replace($pushAnchor,$pushAnchor+"`n    try { Invoke-BridgeTrace -Mode AfterPush } catch { Say ('Push ja concluido; recibo local de rastreio falhou: '+`$_.Exception.Message) }")
 $header="# Bridge-Delivery-ID: TB-20261101T042032Z-817D9FCD`n# Bridge-Base-Commit: c8c885abe4700d57c6dbd846699eb59b6f078840`n"
 $firstLf=$newSource.IndexOf("`n")
 if($firstLf -lt 0){throw 'Sincronizador sem estrutura esperada.'}
 $newSource=$newSource.Insert($firstLf+1,$header)
 $templates=@{
  'tools/Bridge-Rastreabilidade.ps1' = ''
  'RASTREABILIDADE.md' = ''
  'PROMPT-NOVO-CHAT.md' = ''
 }
 $planned=@{}
 foreach($name in $templates.Keys){$planned[$name]=[Convert]::FromBase64String($templates[$name])}
 $planned['Sincronizar-GitHub.ps1']=[Text.UTF8Encoding]::new($true).GetPreamble()+$Utf8.GetBytes($newSource)
 $planned['tools/Instalar-Rastreabilidade.ps1']=[IO.File]::ReadAllBytes($PSCommandPath)
 $readmePath=Join-Path $Root 'README.md'
 $readme=if(Test-Path -LiteralPath $readmePath){[IO.File]::ReadAllText($readmePath)}else{'# The Bridge'}
 $note=@'

<!-- BEGIN BRIDGE DELIVERY PROTOCOL -->
## Entregas rastreaveis e prompt de continuidade

Leia [RASTREABILIDADE.md](RASTREABILIDADE.md) e use [PROMPT-NOVO-CHAT.md](PROMPT-NOVO-CHAT.md). Codigo efetivo continua na main via PC/sincronizador. A branch ai-deliveries guarda propostas GERADAS, nao versao instalada. Cada entrega possui ID e manifesto com hashes; observacoes locais verificam correspondencia sem declarar teste. Esta secao complementa as instrucoes anteriores de consulta ao GitHub e nao altera o gameplay.
<!-- END BRIDGE DELIVERY PROTOCOL -->
'@
 if($readme.Contains('<!-- BEGIN BRIDGE DELIVERY PROTOCOL -->')){throw 'Protocolo ja parece instalado. Nao dupliquei.'}
 $readme="<!-- Bridge-Delivery-ID: TB-20261101T042032Z-817D9FCD -->`n<!-- Bridge-Base-Commit: c8c885abe4700d57c6dbd846699eb59b6f078840 -->`n"+$readme.TrimStart([char]0xFEFF).TrimEnd()+"`n"+$note+"`n"
 $planned['README.md']=$Utf8.GetBytes($readme)

 foreach($name in $planned.Keys){
  if($name.EndsWith('.ps1')){
   $tokens=$null;$parseErrors=$null
   $null=[System.Management.Automation.Language.Parser]::ParseInput($Utf8.GetString($planned[$name]).TrimStart([char]0xFEFF),[ref]$tokens,[ref]$parseErrors)
   if(@($parseErrors).Count -gt 0){throw ("Sintaxe PowerShell invalida em $name : "+(($parseErrors|ForEach-Object{$_.Message}) -join '; '))}
  }
 }
 $manifestFiles=@()
 foreach($name in ($planned.Keys|Sort-Object)){$manifestFiles+=,[ordered]@{path=$name;sha256_normalized_utf8_lf=(Canon $planned[$name])}}
 $manifest=[ordered]@{schema_version=1;delivery_id='TB-20261101T042032Z-817D9FCD';status='GERADA';created_at='2026-11-01T04:20:32.719526Z';base_commit='c8c885abe4700d57c6dbd846699eb59b6f078840';prepared_on_commit=$head;objective='Adicionar ledger separado, IDs, hashes e observacoes do sincronizador sem alterar gameplay.';hash_algorithm='utf8-lf-no-bom-v1';files=$manifestFiles;changes=@('Hooks BeforeCommit e AfterPush no sincronizador auditado','Ledger separado de propostas','Manifestos e observacoes com SHA-256 normalizado','Prompt e protocolo de continuidade');must_preserve=@('main recebe codigo pelo PC','Filtro textual e protecoes existentes','Nenhum script do Minecraft modificado');dependencies=@('Sincronizador com hooks exige tools/Bridge-Rastreabilidade.ps1');tests_performed=@('Ensaios de hash/classificacao e fluxo Git em ambiente temporario, conforme relatorio do pacote; PowerShell nao executado');tests_pending=@('Instalacao Windows','Uma observacao estavel sem loop de commits','Entrega parcial/divergente','Confirmação de push e recibo local');relates_to=@()}
 $manifestJson=($manifest|ConvertTo-Json -Depth 30)+"`n"
 Write-Host "Projeto: $Root"
 Write-Host 'Instala helpers/documentos e dois hooks no sincronizador. Nao altera scripts do jogo nem gitignore.'
 Write-Host 'Com sua confirmacao: cria/atualiza SOMENTE a branch ai-deliveries com este registro GERADA.'
