 Write-Host 'O monitor deve continuar parado durante a instalacao. Sera pausado na configuracao ate concluir.'
 Write-Host "ID: TB-20261101T042032Z-817D9FCD"
 if((Read-Host 'Para autorizar a instalacao local e registro remoto na ai-deliveries, digite INSTALAR').Trim() -cne 'INSTALAR'){throw 'Cancelado antes da instalacao.'}
 $backup=Join-Path $Root ('.git/bridge-trace/install-backup-'+(Get-Date -Format 'yyyyMMdd-HHmmss'))
 [void](New-Item -ItemType Directory -Path $backup -Force)
 $cfg=Get-Content -LiteralPath $CfgPath -Raw|ConvertFrom-Json
 Copy-Item -LiteralPath $CfgPath -Destination (Join-Path $backup 'bridge-sync.json')
 foreach($name in $planned.Keys){$f=Join-Path $Root $name;if(Test-Path -LiteralPath $f -PathType Leaf){$b=Join-Path $backup $name;[void](New-Item -ItemType Directory -Path (Split-Path $b) -Force);Copy-Item -LiteralPath $f -Destination $b}}
 $cfg|Add-Member -NotePropertyName Enabled -NotePropertyValue $false -Force
 [IO.File]::WriteAllText($CfgPath,($cfg|ConvertTo-Json -Depth 10),$Utf8)
 $TempRepo=Join-Path ([IO.Path]::GetTempPath()) ('bridge-ledger-'+[guid]::NewGuid().ToString('N'))
 [void](New-Item -ItemType Directory -Path $TempRepo)
 $null=GitAt -Dir $TempRepo -A @('init','-b','ai-deliveries')
 foreach($k in @('user.name','user.email')){$v=(G -A @('config','--get',$k)).Text;if([string]::IsNullOrWhiteSpace($v)){throw 'Identidade Git incompleta.'};$null=GitAt -Dir $TempRepo -A @('config','--local',$k,$v)}
 $null=GitAt -Dir $TempRepo -A @('remote','add','origin',$origin)
 $exists=G -A @('ls-remote','--exit-code','--heads','origin','refs/heads/ai-deliveries') -Ok @(0,2)
 if($exists.Code -eq 0){
  $null=GitAt -Dir $TempRepo -A @('fetch','--depth=1','origin','refs/heads/ai-deliveries')
  $null=GitAt -Dir $TempRepo -A @('checkout','-B','ai-deliveries','FETCH_HEAD')
 }
 $entry=Join-Path $TempRepo 'entregas/TB-20261101T042032Z-817D9FCD.json'
 [void](New-Item -ItemType Directory -Path (Split-Path $entry) -Force)
 $needCommit=$true
 if(Test-Path -LiteralPath $entry){
  if((Canon ([IO.File]::ReadAllBytes($entry))) -ne (Canon ($Utf8.GetBytes($manifestJson)))){throw 'Esse ID ja tem outro conteudo no ledger. Nao sobrescrevi.'}
