 foreach($name in $planned.Keys){$dest=Join-Path $Root $name;[void](New-Item -ItemType Directory -Path (Split-Path $dest) -Force);[IO.File]::WriteAllBytes($dest,$planned[$name])}
 $received=Join-Path $Root 'RASTREABILIDADE/recebidas/TB-20261101T042032Z-817D9FCD.json'
 [void](New-Item -ItemType Directory -Path (Split-Path $received) -Force)
 [IO.File]::WriteAllText($received,$manifestJson,$Utf8)
 $cfg|Add-Member -NotePropertyName Enabled -NotePropertyValue $true -Force
 [IO.File]::WriteAllText($CfgPath,($cfg|ConvertTo-Json -Depth 10),$Utf8)
 Write-Host "`nINSTALADO LOCALMENTE. Registro GERADA salvo na branch ai-deliveries." -ForegroundColor Green
