 Write-Host 'Nao apague .git. Se a preparacao iniciou, a configuracao pode estar pausada. Preserve o backup.'
 if($null -ne $TempRepo){Write-Host "Metadata temporaria preservada: $TempRepo"}
 exit 1
}finally{
